def make(maxsize=None):
    calls = []
    @memoize(maxsize=maxsize)
    def square(x, *, scale=1):
        """Squares x."""
        calls.append(x)
        return x * x * scale
    return square, calls

@test("repeated calls hit the cache")
def _():
    f, calls = make()
    assert [f(3), f(3), f(4), f(3)] == [9, 9, 16, 9]
    assert calls == [3, 4], f"the real function ran for {calls}"

@test("keyword arguments are part of the key")
def _():
    f, calls = make()
    assert f(2, scale=10) == 40
    assert f(2) == 4
    assert f(2, scale=10) == 40
    assert calls == [2, 2], f"the real function ran for {calls}"

@test("keyword order doesn't matter")
def _():
    seen = []
    @memoize()
    def g(*, a, b):
        seen.append((a, b))
        return a - b
    assert g(a=5, b=2) == 3 and g(b=2, a=5) == 3
    assert len(seen) == 1, f"ran {len(seen)} times"

@test("maxsize evicts the least recently used entry")
def _():
    f, calls = make(maxsize=2)
    f(1); f(2); f(1)   # 1 is now the most recently used
    f(3)               # evicts 2, not 1
    calls.clear()
    f(1)
    assert calls == [], "1 should still be cached (it was used recently)"
    f(2)
    assert calls == [2], "2 should have been evicted"

@test("cache_info counts hits, misses and size")
def _():
    f, _calls = make(maxsize=2)
    f(1); f(1); f(2); f(3)
    assert f.cache_info() == {"hits": 1, "misses": 3, "size": 2}, f"cache_info() = {f.cache_info()}"

@test("cache_clear empties the cache and resets counts")
def _():
    f, calls = make()
    f(1); f(1)
    f.cache_clear()
    assert f.cache_info() == {"hits": 0, "misses": 0, "size": 0}
    f(1)
    assert calls == [1, 1]

@test("exceptions are not cached")
def _():
    attempts = []
    @memoize()
    def flaky(x):
        attempts.append(x)
        if len(attempts) == 1:
            raise RuntimeError("first call fails")
        return x
    raises(RuntimeError, flaky, 7)
    assert flaky(7) == 7 and len(attempts) == 2

@test("the wrapper keeps the name and docstring")
def _():
    f, _calls = make()
    assert f.__name__ == "square", f"__name__ is {f.__name__!r}"
    assert f.__doc__ == "Squares x."

@test("each function has its own cache")
def _():
    f, fc = make()
    g, gc = make()
    f(2); g(2)
    assert fc == [2] and gc == [2]

